def min_subarray_sum(nums):
    if not nums:
        raise ValueError("Input array must not be empty")

    min_sum = current_sum = nums[0]

    for num in nums[1:]:
        current_sum = min(num, current_sum + num)
        min_sum = min(min_sum, current_sum)

    return min_sum
